export const getReportsSummaryUrl = (bookId: string, params?: ReportsSummaryParams) => {
	const normalizedParams = new URLSearchParams();

	Object.entries(params || {}).forEach(([key, value]) => {
		if (value !== undefined) {
			normalizedParams.append(key, value === null ? "null" : String(value));
		}
	});

	const stringifiedParams = normalizedParams.toString();

	return stringifiedParams.length > 0
		? `/api/v1/books/${bookId}/reports/summary?${stringifiedParams}`
		: `/api/v1/books/${bookId}/reports/summary`;
};

/**
 * @summary Summary
 */
export const reportsSummary = async (
	bookId: string,
	params?: ReportsSummaryParams,
	options?: Parameters<typeof apiFetch>[1],
): Promise<SummaryResponse> => {
	return apiFetch<SummaryResponse>(getReportsSummaryUrl(bookId, params), {
		...options,
		method: "GET",
	});
};

export const getReportsSummaryQueryKey = (bookId: string, params?: ReportsSummaryParams) => {
	return [`/api/v1/books/${bookId}/reports/summary`, ...(params ? [params] : [])] as const;
};

export const useReportsSummaryQueryOptions = <
	TData = Awaited<ReturnType<typeof reportsSummary>>,
	TError = ErrorType<HTTPValidationError>,
>(
	bookId: string,
	params?: ReportsSummaryParams,
	options?: {
		query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof reportsSummary>>, TError, TData>>;
		request?: SecondParameter<typeof apiFetch>;
	},
) => {
	const { query: queryOptions, request: requestOptions } = options ?? {};

	const queryKey = queryOptions?.queryKey ?? getReportsSummaryQueryKey(bookId, params);

	const queryFn: QueryFunction<Awaited<ReturnType<typeof reportsSummary>>> = ({ signal }) =>
		reportsSummary(bookId, params, { signal, ...requestOptions });

	const customOptions = queryDefaults({
		queryKey,
		queryFn,
		enabled: bookId !== null && bookId !== undefined,
		...queryOptions,
	});

	return customOptions as UseQueryOptions<
		Awaited<ReturnType<typeof reportsSummary>>,
		TError,
		TData
	> & { queryKey: DataTag<QueryKey, TData, TError> };
};

